def card(p):
    """Format a vocabulary profile as a plain-text terminal card."""
    lines = []

    if "word_count" in p:
        lines.append(f"Length:      {p['word_count']} words")

    if "unique_words" in p:
        lines.append(f"Vocabulary:  {p['unique_words']} unique")

    if "top_words" in p and p["top_words"]:
        top = ", ".join(f"'{word}' ({count})" for word, count in p["top_words"])
        lines.append(f"Dominated:   {top}")

    return "\n".join(lines)
